from collections import deque

def _find_cycle_debug(deps, all_packages, sorted_set):
    cycle_packages = all_packages - sorted_set
    if not cycle_packages:
        return []

    rev_adj = {pkg: [] for pkg in cycle_packages}
    for pkg in cycle_packages:
        if pkg in deps:
            for d in deps[pkg]:
                if d in cycle_packages:
                    rev_adj[pkg].append(d)

    print(f"cycle_packages: {cycle_packages}")
    print(f"rev_adj: {rev_adj}")

    start = min(cycle_packages)
    print(f"start: {start}")

    path = []
    path_set = {start}
    visited = {start}
    stack = [(start, 0)]

    step = 0
    while stack:
        print(f"  Step {step}: stack={stack}, path={path}, path_set={path_set}, visited={visited}")
        node, idx = stack[-1]
        neighbors = rev_adj.get(node, [])

        if idx < len(neighbors):
            stack[-1] = (node, idx + 1)
            neighbor = neighbors[idx]
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                path_set.add(neighbor)
                stack.append((neighbor, 0))
            elif neighbor in path_set:
                print(f"  CYCLE FOUND: neighbor={neighbor}, path={path}")
                idx_in_path = path.index(neighbor)
                cycle = path[idx_in_path:]
                min_pkg = min(cycle)
                min_idx = cycle.index(min_pkg)
                return cycle[min_idx:] + cycle[:min_idx]
        else:
            path.pop()
            path_set.discard(node)
            stack.pop()
        step += 1

    return sorted(cycle_packages)

# Test: a -> b -> a
result = _find_cycle_debug({'a': ['b'], 'b': ['a']}, {'a', 'b'}, set())
print(f"Result: {result}")

